@import '../../utils/button-base.css';
@import '../../utils/button-split.css';

:host {
  --ds-button-filled-bg: var(--color-background-bold-brand);
  --ds-button-filled-fg: var(--color-foreground-faint-brand);
  --ds-button-filled-border: var(--color-border-secondary);
  --ds-button-split-border: var(--color-border-secondary);
  --ds-button-split-divider: var(--color-border-on-bold-background-tertiary);
}

:host(.button-filled-host--contrast-strong) {
  --ds-button-split-divider: var(--color-border-on-strong-background-tertiary);
}

:host(.button-filled-host--contrast-medium) {
  --ds-button-split-divider: var(--color-border-on-medium-background-tertiary);
}

:host(.button-filled-host--contrast-faint) {
  --ds-button-split-divider: var(--color-border-tertiary);
}

:host(.button-filled-host--background-medium) {
  --ds-button-split-border: var(--color-border-on-medium-background-secondary);
}

:host(.button-filled-host--background-bold) {
  --ds-button-split-border: var(--color-border-on-bold-background-secondary);
}

:host(.button-filled-host--background-strong) {
  --ds-button-split-border: var(--color-border-on-strong-background-secondary);
}

:host(.button-filled-host--background-translucent) {
  --ds-button-split-border: var(--color-translucent-border-secondary);
}

:host(.button-filled-host--background-inverted) {
  --ds-button-split-border: var(--color-inverted-border-secondary);
}

:host(.button-filled-host--background-media) {
  --ds-button-split-border: var(--color-media-border-secondary);
}

:host(.button-filled-host--background-always-dark) {
  --ds-button-split-border: var(--color-always-dark-border-secondary);
}

.button-filled {
  background-color: var(--ds-button-filled-bg);
  color: var(--ds-button-filled-fg);
  transition:
    background-color var(--effect-motion-short-2),
    color var(--effect-motion-short-2);
  /* Hover/press: `.ds-interaction-fill` + contrast → `--on-*` (token overlay, not color-mix). */
}

/*
 * An open popup is a transient pressed state, not a selected state. ButtonFilled
 * deliberately has no active state, so hold the pressed wash for the popup's
 * complete rendered lifecycle instead of promoting any selected treatment.
 */
/* Inset stroke via interaction-fill ::after (above hover and pressed washes). */
.button-filled--bordered {
  --ds-interaction-border-color: var(--ds-button-filled-border);
}

/*
 * Parent-surface context affects only the optional inset border.
 * Intent + contrast continue to own fill, foreground, and interaction overlays.
 */
.button-filled--background-medium {
  --ds-button-filled-border: var(--color-border-on-medium-background-secondary);
}

.button-filled--background-bold {
  --ds-button-filled-border: var(--color-border-on-bold-background-secondary);
}

.button-filled--background-strong {
  --ds-button-filled-border: var(--color-border-on-strong-background-secondary);
}

.button-filled--background-translucent {
  --ds-button-filled-border: var(--color-translucent-border-secondary);
}

.button-filled--background-inverted {
  --ds-button-filled-border: var(--color-inverted-border-secondary);
}

.button-filled--background-media {
  --ds-button-filled-border: var(--color-media-border-secondary);
}

.button-filled--background-always-dark {
  --ds-button-filled-border: var(--color-always-dark-border-secondary);
}

/* Inactive: `.ds-control-inactive` (50% opacity). */

/* ── Intent + contrast (bold default) ─────────────────────────────────────── */

.button-filled--intent-neutral {
  --ds-button-filled-bg: var(--color-background-bold-neutral);
  --ds-button-filled-fg: var(--color-foreground-faint-neutral);
}

.button-filled--intent-brand {
  --ds-button-filled-bg: var(--color-background-bold-brand);
  --ds-button-filled-fg: var(--color-foreground-faint-brand);
}

.button-filled--intent-ai {
  --ds-button-filled-bg: var(--color-background-bold-ai);
  --ds-button-filled-fg: var(--color-foreground-faint-ai);
}

.button-filled--intent-negative {
  --ds-button-filled-bg: var(--color-background-bold-negative);
  --ds-button-filled-fg: var(--color-foreground-faint-negative);
}

.button-filled--intent-warning {
  --ds-button-filled-bg: var(--color-background-bold-warning);
  --ds-button-filled-fg: var(--color-foreground-faint-warning);
}

.button-filled--intent-caution {
  --ds-button-filled-bg: var(--color-background-bold-caution);
  --ds-button-filled-fg: var(--color-foreground-faint-caution);
}

.button-filled--intent-positive {
  --ds-button-filled-bg: var(--color-background-bold-positive);
  --ds-button-filled-fg: var(--color-foreground-faint-positive);
}

.button-filled--intent-guide {
  --ds-button-filled-bg: var(--color-background-bold-guide);
  --ds-button-filled-fg: var(--color-foreground-faint-guide);
}

.button-filled--intent-walkthrough {
  --ds-button-filled-bg: var(--color-background-bold-walkthrough);
  --ds-button-filled-fg: var(--color-foreground-faint-walkthrough);
}

/* strong → medium fg */
.button-filled--contrast-strong.button-filled--intent-neutral {
  --ds-button-filled-bg: var(--color-background-strong-neutral);
  --ds-button-filled-fg: var(--color-foreground-medium-neutral);
}

.button-filled--contrast-strong.button-filled--intent-brand {
  --ds-button-filled-bg: var(--color-background-strong-brand);
  --ds-button-filled-fg: var(--color-foreground-medium-brand);
}

.button-filled--contrast-strong.button-filled--intent-ai {
  --ds-button-filled-bg: var(--color-background-strong-ai);
  --ds-button-filled-fg: var(--color-foreground-medium-ai);
}

.button-filled--contrast-strong.button-filled--intent-negative {
  --ds-button-filled-bg: var(--color-background-strong-negative);
  --ds-button-filled-fg: var(--color-foreground-medium-negative);
}

.button-filled--contrast-strong.button-filled--intent-warning {
  --ds-button-filled-bg: var(--color-background-strong-warning);
  --ds-button-filled-fg: var(--color-foreground-medium-warning);
}

.button-filled--contrast-strong.button-filled--intent-caution {
  --ds-button-filled-bg: var(--color-background-strong-caution);
  --ds-button-filled-fg: var(--color-foreground-medium-caution);
}

.button-filled--contrast-strong.button-filled--intent-positive {
  --ds-button-filled-bg: var(--color-background-strong-positive);
  --ds-button-filled-fg: var(--color-foreground-medium-positive);
}

.button-filled--contrast-strong.button-filled--intent-guide {
  --ds-button-filled-bg: var(--color-background-strong-guide);
  --ds-button-filled-fg: var(--color-foreground-medium-guide);
}

.button-filled--contrast-strong.button-filled--intent-walkthrough {
  --ds-button-filled-bg: var(--color-background-strong-walkthrough);
  --ds-button-filled-fg: var(--color-foreground-medium-walkthrough);
}

/* medium → strong fg */
.button-filled--contrast-medium.button-filled--intent-neutral {
  --ds-button-filled-bg: var(--color-background-medium-neutral);
  --ds-button-filled-fg: var(--color-foreground-strong-neutral);
}

.button-filled--contrast-medium.button-filled--intent-brand {
  --ds-button-filled-bg: var(--color-background-medium-brand);
  --ds-button-filled-fg: var(--color-foreground-strong-brand);
}

.button-filled--contrast-medium.button-filled--intent-ai {
  --ds-button-filled-bg: var(--color-background-medium-ai);
  --ds-button-filled-fg: var(--color-foreground-strong-ai);
}

.button-filled--contrast-medium.button-filled--intent-negative {
  --ds-button-filled-bg: var(--color-background-medium-negative);
  --ds-button-filled-fg: var(--color-foreground-strong-negative);
}

.button-filled--contrast-medium.button-filled--intent-warning {
  --ds-button-filled-bg: var(--color-background-medium-warning);
  --ds-button-filled-fg: var(--color-foreground-strong-warning);
}

.button-filled--contrast-medium.button-filled--intent-caution {
  --ds-button-filled-bg: var(--color-background-medium-caution);
  --ds-button-filled-fg: var(--color-foreground-strong-caution);
}

.button-filled--contrast-medium.button-filled--intent-positive {
  --ds-button-filled-bg: var(--color-background-medium-positive);
  --ds-button-filled-fg: var(--color-foreground-strong-positive);
}

.button-filled--contrast-medium.button-filled--intent-guide {
  --ds-button-filled-bg: var(--color-background-medium-guide);
  --ds-button-filled-fg: var(--color-foreground-strong-guide);
}

.button-filled--contrast-medium.button-filled--intent-walkthrough {
  --ds-button-filled-bg: var(--color-background-medium-walkthrough);
  --ds-button-filled-fg: var(--color-foreground-strong-walkthrough);
}

/* faint → bold fg */
.button-filled--contrast-faint.button-filled--intent-neutral {
  --ds-button-filled-bg: var(--color-background-faint-neutral);
  --ds-button-filled-fg: var(--color-foreground-bold-neutral);
}

.button-filled--contrast-faint.button-filled--intent-brand {
  --ds-button-filled-bg: var(--color-background-faint-brand);
  --ds-button-filled-fg: var(--color-foreground-bold-brand);
}

.button-filled--contrast-faint.button-filled--intent-ai {
  --ds-button-filled-bg: var(--color-background-faint-ai);
  --ds-button-filled-fg: var(--color-foreground-bold-ai);
}

.button-filled--contrast-faint.button-filled--intent-negative {
  --ds-button-filled-bg: var(--color-background-faint-negative);
  --ds-button-filled-fg: var(--color-foreground-bold-negative);
}

.button-filled--contrast-faint.button-filled--intent-warning {
  --ds-button-filled-bg: var(--color-background-faint-warning);
  --ds-button-filled-fg: var(--color-foreground-bold-warning);
}

.button-filled--contrast-faint.button-filled--intent-caution {
  --ds-button-filled-bg: var(--color-background-faint-caution);
  --ds-button-filled-fg: var(--color-foreground-bold-caution);
}

.button-filled--contrast-faint.button-filled--intent-positive {
  --ds-button-filled-bg: var(--color-background-faint-positive);
  --ds-button-filled-fg: var(--color-foreground-bold-positive);
}

.button-filled--contrast-faint.button-filled--intent-guide {
  --ds-button-filled-bg: var(--color-background-faint-guide);
  --ds-button-filled-fg: var(--color-foreground-bold-guide);
}

.button-filled--contrast-faint.button-filled--intent-walkthrough {
  --ds-button-filled-bg: var(--color-background-faint-walkthrough);
  --ds-button-filled-fg: var(--color-foreground-bold-walkthrough);
}

/*
 * Bold, strong, and medium fills already communicate semantic intent. Their
 * on-background foreground tokens preserve AA text contrast across themes,
 * including brand pairs whose chromatic counterparts sit on the 4.5:1 edge.
 */
.button-filled--contrast-bold.button-filled {
  --ds-button-filled-fg: var(--color-foreground-on-bold-background-primary);
}

.button-filled--contrast-strong.button-filled {
  --ds-button-filled-fg: var(--color-foreground-on-strong-background-primary);
}

.button-filled--contrast-medium.button-filled {
  --ds-button-filled-fg: var(--color-foreground-on-medium-background-primary);
}

import { Component, Element, Event, EventEmitter, h, Host, Method, Prop } from '@stencil/core';
import { controlWidthClass } from '../../utils';
import type { ChoiceBackground } from '../../utils/choice-list';
import { beginElevatedControlPress } from '../../utils/control-press';
import { renderButtonContent } from '../../utils/button-render';
import type { ControlInsetDepth } from '../../utils/control-text';
import type { ButtonPopup, ButtonSize, ButtonVariant, ButtonWidth } from '../../utils/button-types';

export type ButtonFilledIntent =
  | 'neutral'
  | 'brand'
  | 'ai'
  | 'negative'
  | 'warning'
  | 'caution'
  | 'positive'
  | 'guide'
  | 'walkthrough';

export type ButtonFilledContrast = 'bold' | 'strong' | 'medium' | 'faint';

export type ButtonFilledBackground = ChoiceBackground;

export type ButtonFilledVariant = ButtonVariant;
export type ButtonFilledSize = ButtonSize;
export type ButtonFilledWidth = ButtonWidth;
export type ButtonFilledPopup = ButtonPopup;

@Component({
  tag: 'ds-button-filled',
  styleUrl: 'ButtonFilled.css',
  scoped: true,
})
export class ButtonFilled {
  @Element() el!: HTMLElement;

  /**
   * Content layout. Default is label-only; pass `icon` for icon-only chrome
   * (nav / tool rails) or `icon-label` for leading icon + text.
   */
  @Prop() variant: ButtonFilledVariant = 'label';

  /** Control density (height, padding, icon, type). */
  @Prop() size: ButtonFilledSize = 'md';

  /** Use reduced outer geometry when nested inside a control of the same size. */
  @Prop() isInset: boolean = false;

  /** Single removes 4px overall; double removes 8px overall (xs stays single). */
  @Prop() insetDepth: ControlInsetDepth = 'single';

  /** Width fit — hug content (default) or fill the parent. */
  @Prop() width: ButtonFilledWidth = 'hug';

  /** Visible text for `label` / `icon-label` variants. */
  @Prop() label: string = '';

  /** Whether the visible label uses the emphasized weight. */
  @Prop() labelEmphasis: boolean = true;

  /** Icon name passed to <ds-icon> for `icon` / `icon-label` variants. */
  @Prop() icon: string = '';

  /** Semantic colour intent. */
  @Prop() intent: ButtonFilledIntent = 'brand';

  /**
   * Background fill weight. Foreground uses the paired contrast token:
   * bold → faint, strong → medium, medium → strong, faint → bold.
   */
  @Prop() contrast: ButtonFilledContrast = 'bold';

  /** Show a 1px secondary inset border. */
  @Prop() hasBorder: boolean = false;

  /**
   * Actual parent surface context for the optional inset border color only.
   * Omit on primary and secondary surfaces.
   */
  @Prop() background: ButtonFilledBackground | undefined;

  /** Use the half-radius treatment instead of the default control radius. */
  @Prop() rounded: boolean = false;

  /**
   * Scale down during a physical pointer press.
   * Disable when an owning composite requires fixed child or background geometry.
   */
  @Prop() pressScale: boolean = true;

  /** Disables interaction. */
  @Prop() isInactive: boolean = false;

  /** Shows an inline loader and prevents interaction without applying inactive opacity. */
  @Prop() isLoading: boolean = false;

  /** Native button type. */
  @Prop() type: 'button' | 'submit' | 'reset' = 'button';

  /** Accessible name override. Required for icon-only buttons. */
  @Prop({ attribute: 'aria-label' }) ariaLabel: string | null = null;

  /** ID of the popup this button controls. */
  @Prop() controls: string | undefined;

  /**
   * Controlled open state of the popup this button triggers. Holds the pressed
   * wash for the popup's rendered lifecycle. ButtonFilled has no selected state,
   * so an open popup never promotes to an active treatment.
   */
  @Prop() expanded: boolean | undefined;

  /** Popup type exposed to assistive technology. */
  @Prop() haspopup: ButtonFilledPopup | undefined;

  /**
   * Append a separate ChevronDown menu segment while preserving this button's
   * variant, size, intent, contrast, loading, inactive, and width treatment.
   */
  @Prop() split: boolean = false;

  /** Accessible name for the appended menu segment in split mode. */
  @Prop() menuAriaLabel: string = 'More options';

  /**
   * This action *has* a menu: implies `aria-haspopup="menu"` and adds the trailing
   * chevron that carries the affordance.
   *
   * Only `label` and `icon-label` are supported. A filled button is never the
   * overflow / more-options control — that role belongs to ButtonUnfilled with an
   * `Ellipses` glyph, which conveys the menu without a chevron.
   *
   * Use `haspopup` directly for non-menu popups.
   */
  @Prop() hasMenu: boolean = false;

  @Event() dsClick!: EventEmitter<MouseEvent>;
  @Event() dsMenuClick!: EventEmitter<MouseEvent>;

  private buttonEl: HTMLButtonElement | null = null;
  private menuButtonEl: HTMLButtonElement | null = null;

  @Method()
  async setFocus(segment: 'primary' | 'menu' = 'primary') {
    (segment === 'menu' ? this.menuButtonEl : this.buttonEl)?.focus();
  }

  private handleClick = (event: MouseEvent) => {
    if (this.isInactive || this.isLoading) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    this.dsClick.emit(event);
  };

  private handleMenuClick = (event: MouseEvent) => {
    if (this.isInactive || this.isLoading) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    this.dsMenuClick.emit(event);
  };

  private get resolvedHaspopup(): ButtonFilledPopup | undefined {
    return this.haspopup ?? (this.hasMenu ? 'menu' : undefined);
  }

  private get accessibleName(): string | undefined {
    if (this.ariaLabel) return this.ariaLabel;
    if (this.isLoading && this.variant === 'label' && this.label) return this.label;
    return undefined;
  }

  private get doubleInset(): boolean {
    return this.isInset && this.insetDepth === 'double' && this.size !== 'xs';
  }

  private buttonClass(
    variant: ButtonFilledVariant,
    expanded: boolean,
    bordered: boolean
  ): Record<string, boolean> {
    const cls: Record<string, boolean> = {
      'button-filled': true,
      'ds-button': true,
      'ds-focus-ring-inset': true,
      'ds-control-press-scale': this.pressScale && !this.split,
      'ds-interaction-fill': !this.isInactive,
      /* Bold is the default filled contrast — on-bold interaction tokens. */
      'ds-interaction-fill--on-bold': this.contrast === 'bold',
      'ds-interaction-fill--on-strong': this.contrast === 'strong',
      'ds-interaction-fill--on-medium': this.contrast === 'medium',
      /* faint → default app interaction tokens (no --on-*). */
      'button-filled--bordered': bordered,
      'ds-button--bordered': bordered,
      'button-filled--expanded': expanded && !this.isInactive,
      'ds-button--expanded': expanded && !this.isInactive,
      'ds-control-inactive': this.isInactive,
      'ds-control--lg': this.size === 'lg',
      'ds-control--md': this.size === 'md',
      'ds-control--sm': this.size === 'sm',
      'ds-control--xs': this.size === 'xs',
      'ds-control--inset': this.isInset && !this.doubleInset,
      'ds-control--inset-double': this.doubleInset,
      'ds-control-frame': true,
      'button-filled--icon': variant === 'icon',
      'ds-button--icon': variant === 'icon',
      'button-filled--label': variant === 'label',
      'button-filled--icon-label': variant === 'icon-label',
      'button-filled--rounded': this.rounded,
      'ds-button--rounded': this.rounded,
      [`button-filled--background-${this.background}`]: this.background !== undefined,
      [`button-filled--intent-${this.intent}`]: true,
      [`button-filled--contrast-${this.contrast}`]: true,
    };
    return cls;
  }

  render() {
    const primaryButton = (
      <button
        ref={el => {
          this.buttonEl = el ?? null;
        }}
        type={this.type}
        class={{
          ...this.buttonClass(
            this.variant,
            !this.split && this.expanded === true,
            this.hasBorder && !this.split
          ),
          'ds-button-split__primary': this.split,
        }}
        disabled={this.isInactive}
        aria-label={this.accessibleName}
        aria-busy={this.isLoading ? 'true' : undefined}
        aria-disabled={this.isLoading ? 'true' : undefined}
        aria-controls={this.split ? undefined : this.controls}
        aria-expanded={
          this.split || this.expanded === undefined ? undefined : String(this.expanded)
        }
        aria-haspopup={this.split ? undefined : this.resolvedHaspopup}
        onPointerDown={event =>
          beginElevatedControlPress(
            event,
            this.pressScale && !this.split && !this.isInactive && !this.isLoading
          )
        }
        onClick={this.handleClick}
      >
        {renderButtonContent({
          namespace: 'button-filled',
          variant: this.variant,
          size: this.size,
          label: this.label,
          labelEmphasis: this.labelEmphasis,
          icon: this.icon,
          hasMenu: !this.split && this.hasMenu,
          isLoading: this.isLoading,
        })}
      </button>
    );

    const control = this.split ? (
      <div
        class={{
          'ds-button-split': true,
          'ds-button-split--rounded': this.rounded,
        }}
      >
        {primaryButton}
        <span class="ds-button-split__divider" aria-hidden="true" />
        <button
          ref={el => {
            this.menuButtonEl = el ?? null;
          }}
          class={{
            ...this.buttonClass('icon', this.expanded === true, false),
            'ds-button-split__menu': true,
          }}
          type="button"
          disabled={this.isInactive || this.isLoading}
          aria-label={this.menuAriaLabel}
          aria-controls={this.controls}
          aria-expanded={String(this.expanded === true)}
          aria-haspopup="menu"
          onClick={this.handleMenuClick}
        >
          {renderButtonContent({
            namespace: 'button-filled',
            variant: 'icon',
            size: this.size,
            label: '',
            labelEmphasis: true,
            icon: 'ChevronDown',
            hasMenu: false,
            isLoading: false,
          })}
        </button>
        {this.hasBorder ? <span class="ds-button-split__outline" aria-hidden="true" /> : null}
      </div>
    ) : (
      primaryButton
    );

    return (
      <Host
        class={{
          'button-filled-host': true,
          'button-filled-host--icon': this.variant === 'icon' && !this.split,
          'ds-button-host--icon': this.variant === 'icon' && !this.split,
          'ds-button-split-host': this.split,
          'ds-button-split-host--primary-icon': this.split && this.variant === 'icon',
          [`button-filled-host--contrast-${this.contrast}`]: this.split,
          [`button-filled-host--background-${this.background}`]:
            this.split && this.background !== undefined,
          'ds-control--lg': this.size === 'lg',
          'ds-control--md': this.size === 'md',
          'ds-control--sm': this.size === 'sm',
          'ds-control--xs': this.size === 'xs',
          'ds-control--inset': this.isInset && !this.doubleInset,
          'ds-control--inset-double': this.doubleInset,
          ...controlWidthClass(this.width),
        }}
        tabIndex={-1}
      >
        {control}
      </Host>
    );
  }
}
